// Turn the bundled CSL styles and locale in src/lib/references/csl/source/
// into TypeScript modules that export the XML as strings, so the client, the
// citation worker and the server can load them with a plain dynamic import()
// and no bundler loader. Run after updating a source file:
//
//   node scripts/references/build-csl-assets.cjs
//
// The styles and locales come from the Citation Style Language project and
// are licensed CC BY-SA 3.0; the attribution travels in each generated file.

const fs = require("node:fs");
const path = require("node:path");

const root = path.resolve(__dirname, "../..");
const cslDirectory = path.join(root, "src/lib/references/csl");
const sourceDirectory = path.join(cslDirectory, "source");

// Bundled style id → source file. The CSL repository moved the classic
// Vancouver style to the dependent `vancouver-nlm`, whose independent parent
// is `nlm-citation-sequence`; the parent is bundled under the `vancouver` id.
const STYLES = {
  apa: "apa.csl",
  "chicago-author-date": "chicago-author-date.csl",
  ieee: "ieee.csl",
  vancouver: "nlm-citation-sequence.csl",
  nature: "nature.csl",
  "harvard-cite-them-right": "harvard-cite-them-right.csl",
};

const LOCALES = {
  "en-US": "locales-en-US.xml",
};

const HEADER = `// GENERATED by scripts/references/build-csl-assets.cjs from
// src/lib/references/csl/source/. Do not edit by hand.
//
// Citation Style Language styles and locales, © their authors and the
// Citation Style Language project (https://citationstyles.org,
// https://github.com/citation-style-language), licensed under the Creative
// Commons Attribution-ShareAlike 3.0 License
// (https://creativecommons.org/licenses/by-sa/3.0/). See ./README.md.
`;

function read(file) {
  const xml = fs.readFileSync(path.join(sourceDirectory, file), "utf8").replace(/^﻿/, "").replace(/\r\n/g, "\n");
  if (!xml.includes("creativecommons.org/licenses/by-sa/3.0")) throw new Error(`${file} lost its CC BY-SA 3.0 rights statement.`);
  return xml;
}

function checkIndependent(id, file, xml) {
  if (/rel="independent-parent"/.test(xml)) throw new Error(`${file} (${id}) is a dependent style; bundle its parent instead.`);
  if (!/<citation[\s>]/.test(xml)) throw new Error(`${file} (${id}) has no <citation> element.`);
}

function moduleSource(exportName, type, entries) {
  const lines = entries.map(([id, xml]) => `  ${JSON.stringify(id)}: ${JSON.stringify(xml)},`);
  return `${HEADER}\n${type}export const ${exportName} = {\n${lines.join("\n")}\n};\n`;
}

const styles = Object.entries(STYLES).map(([id, file]) => {
  const xml = read(file);
  checkIndependent(id, file, xml);
  return [id, xml];
});
const locales = Object.entries(LOCALES).map(([id, file]) => [id, read(file)]);

fs.writeFileSync(
  path.join(cslDirectory, "styles.generated.ts"),
  moduleSource(
    "BUNDLED_CSL_STYLE_XML",
    'import type { BundledCslStyleId } from "../types";\n\n/** Style XML by bundled style id. */\n',
    styles,
  ).replace("export const BUNDLED_CSL_STYLE_XML = {", "export const BUNDLED_CSL_STYLE_XML: Record<BundledCslStyleId, string> = {"),
);
fs.writeFileSync(
  path.join(cslDirectory, "locales.generated.ts"),
  moduleSource("CSL_LOCALE_XML", "/** Locale XML by language tag. */\n", locales)
    .replace("export const CSL_LOCALE_XML = {", "export const CSL_LOCALE_XML: Record<string, string> = {"),
);
console.log(`Wrote ${styles.length} styles and ${locales.length} locale(s) to ${path.relative(root, cslDirectory)}.`);
